import assert from "node:assert";

const parser = new StreamingJsonArrayParser<{ id: number; name: string }>();

const r1 = parser.push("  [ {\"id\": 1, \"name\": \"first\" }, ");
assert.strictEqual(r1.length, 1);
assert.strictEqual(r1[0].name, "first");

const r2 = parser.push("{\"id\": 2, \"name\": \"second\"} , ");
assert.strictEqual(r2.length, 1);
assert.strictEqual(r2[0].id, 2);

const r3 = parser.push("{\"id\": 3, \"nested\": { \"a\": 1 }}, ");
assert.strictEqual(r3.length, 1);

console.log("TypeScript Streaming JSON Parser Test Passed!");
